      cards: [
        { id: "g01", q: "Wer ist der Verlader (Versender)?", a: "Ein Industrie- oder Handelsunternehmen. Er ist Auftraggeber für Transport- und Logistikdienstleistungen und übergibt das Gut.", hint: "Verlader = Auftraggeber" },
        { id: "g02", q: "Wie heißt es, wenn der Verlader selbst transportiert?", a: "Werkverkehr." },
        { id: "g03", q: "Was ist die Aufgabe des Spediteurs?", a: "Er besorgt/organisiert den Transport bzw. alle dazugehörigen Dienstleistungen für den Verlader und beauftragt dafür Frachtführer. Er ist Mittler des Güterverkehrs." },
        { id: "g04", q: "Was ist die Aufgabe des Frachtführers?", a: "Er führt die Beförderung der Güter mit eigenen Fahrzeugen/Transportmitteln durch (Straßentransporteure, Reedereien, Luftfahrtgesellschaften, Eisenbahnen)." },
        { id: "g05", q: "Warum steigt die Verhandlungsmacht eines Spediteurs mit dem Sendungsvolumen?", a: "Je mehr Sendungsvolumen er auf sich vereinigt, desto größer ist seine Bündelungsfähigkeit – und damit seine Verhandlungsmacht gegenüber Frachtführern." },
        { id: "g06", q: "Wie nennt man die Spedition auch bildlich?", a: "„Architekt von Transportketten“ bzw. Mittler des Güterverkehrs." },
        { id: "g07", q: "Was bedeutet „Besorgen“ im Speditionsgeschäft?", a: "Die kaufmännisch-organisatorische Auswahl und Kontrolle des Vertragsabschlusses mit Frachtführern, Lagerhaltern und sonstigen Dienstleistern.", important: true },
        { id: "g08", q: "Was ist Selbsteintritt?", a: "Der Spediteur führt die Beförderung selbst durch (eigene Fahrzeuge/Fahrer) – er wird also selbst zum Frachtführer und hat dann Frachtführerpflichten." },
        { id: "g09", q: "Welcher Vertrag besteht zwischen Verlader und Spediteur? (mit Paragraph)", a: "Der Speditionsvertrag nach § 453 HGB: Spediteur besorgt die Versendung, Verlader zahlt die Vergütung.", important: true },
        { id: "g10", q: "Welcher Vertrag besteht zwischen Spediteur und Frachtführer? (mit Paragraph)", a: "Der Frachtvertrag nach § 407 HGB: Frachtführer befördert das Gut und liefert es ab.", important: true },
        { id: "g11", q: "Welcher Vertrag besteht zwischen Verkäufer und Käufer?", a: "Der Kaufvertrag: Ware liefern und Kaufpreis zahlen." },
        { id: "g12", q: "Warum können Warenfluss und Vertragsbeziehungen auseinanderfallen?", a: "Die Ware fließt physisch vom Verkäufer über den Frachtführer zum Käufer – die Verträge laufen aber über den Spediteur (Speditions- und Frachtvertrag)." },
        { id: "g13", q: "Was bedeutet TUL-Logistik?", a: "Transport, Umschlag, Lagerung – die klassischen Leistungen der Spedition.", important: true, hint: "Prof-Hinweis: TUL !!" },
        { id: "g14", q: "Welche Kernpflichten hat der Spediteur nach § 454 HGB? (3 Bereiche)", a: "Planung: Wahl des Beförderungsmittels und -wegs.\nAusführung: Auswahl ausführender Unternehmer, Abschluss von Fracht-, Lager- und Speditionsverträgen, Erteilung von Weisungen/Infos (… oder Selbsteintritt).\nÜberwachung: Sicherung von Schadenersatzansprüchen.", important: true },
        { id: "g15", q: "Welche 4 Entscheidungen muss der Spediteur bei der Besorgung treffen?", a: "1. Beförderungsmittel und Weg (Kette aus Vor-, Haupt-, Nachlauf)\n2. Ausführende Unternehmen (Partner wählen, Verträge)\n3. Informationen und Weisungen weitergeben\n4. Ansprüche sichern (Abweichungen/Schäden dokumentieren)" },
        { id: "g16", q: "Outsourcing: Wann spricht „Mengen & Netz“ für Fremdvergabe, wann für Eigenleistung?", a: "Fremdvergabe: schwankende Mengen, viele Zielorte.\nEigenleistung: stabile Mengen auf eigenen starken Relationen." },
        { id: "g17", q: "Outsourcing: Welche Kriterien entscheiden zwischen Fremdvergabe und Eigenleistung?", a: "Mengen & Netz, Kompetenz, Investitionen, Steuerung, Abhängigkeit." },
        { id: "g18", q: "Wann spricht die Kompetenz eher für Eigenleistung (Insourcing)?", a: "Wenn Logistikkompetenz für das Unternehmen strategisch zentral ist. (Fremdvergabe, wenn Spezialwissen extern verfügbar ist.)" },
        { id: "g19", q: "Wann spricht die Abhängigkeit gegen Outsourcing?", a: "Bei hohen Wechselkosten oder wenigen Ersatzanbietern. (Für Outsourcing: mehrere geeignete Anbieter verfügbar.)" },
        { id: "g20", q: "Was sind die ADSp?", a: "Allgemeine Deutsche Spediteurbedingungen – die AGB, auf deren Grundlage fast alle Speditionen arbeiten." },
        { id: "g21", q: "Worin weichen die ADSp vom HGB ab?", a: "Teilweise v. a. bei der Haftung – zugunsten von Spediteur, Frachtführer und/oder Lagerhalter." },
        { id: "g22", q: "Für welche Leistungen gelten die ADSp – und wann nicht?", a: "Nur für speditionsübliche Leistungen (Speditions-, Fracht-, Lagergeschäfte u. ä.). Sind Verbraucher beteiligt, gelten andere AGB (z. B. Möbel-/Umzugsspedition, Paketdienste)." },
        { id: "g23", q: "B2B vs. B2C – Beispiel aus der Vorlesung?", a: "B2B: Hersteller → Händler (Nike → Snipes).\nB2C: Händler → Privatkonsument (Snipes → Consumer)." }
      ],
